mapper.select:
SELECT task.production_task_id, task.performance_project_id, task.team_id, team.name AS team_name, task.title, task.description, task.start_date, task.due_date, task.status_code, task.blocked_reason, task.created_by_member_id, task.updated_by_member_id, task.created_dttm, task.updated_dttm FROM production_task task JOIN performance_project project ON project.performance_project_id = task.performance_project_id JOIN team ON team.team_id = task.team_id WHERE task.performance_project_id = #{condition.performanceProjectId} AND
AND task.team_id = #{condition.teamId}
AND task.status_code = #{condition.status}
AND task.due_date < #{currentDate} AND task.status_code <> 'COMPLETED'
ORDER BY team.display_order, task.due_date, task.production_task_id LIMIT #{condition.limit} OFFSET #{condition.offset}

mapper.insert:
INSERT INTO production_task (
    performance_project_id, team_id, title, description,
    start_date, due_date, status_code, blocked_reason,
    created_by_member_id, updated_by_member_id
) VALUES (
    #{performanceProjectId}, #{teamId}, #{title}, #{description},
    #{startDate}, #{dueDate}, #{status}, #{blockedReason},
    #{createdByMemberId}, #{updatedByMemberId}
)

mapper.update:
UPDATE production_task
SET updated_by_member_id = #{actorMemberId},
    deleted_dttm = #{deletedDttm}
WHERE production_task_id = #{productionTaskId}
  AND deleted_dttm IS NULL

mapper.insert:
INSERT INTO production_task_history (
    production_task_id, previous_status_code, new_status_code,
    comment, changed_by_member_id, changed_dttm
) VALUES (
    #{productionTaskId}, #{previousStatus}, #{newStatus},
    #{comment}, #{changedByMemberId}, #{changedDttm}
)
